-- hrm.employee_letters: Letters issued to an employee (offer, appointment, confirmation, increment, promotion, transfer, warning, experience, salary certificate) [DOC-04, DOC-05, DOC-07, DOC-08, CMP-06]
create table if not exists hrm.employee_letters (
    id uuid not null,
    company_id uuid not null,
    letter_no text not null,
    employment_id uuid not null,
    template_id uuid not null,
    letter_type text not null,
    data jsonb not null,
    contains_salary boolean not null default false,
    generated_document_id uuid,
    issued_at timestamptz,
    emailed_at timestamptz,
    acknowledged_at timestamptz,
    source_type text,
    source_id uuid,
    workflow_instance_id uuid,
    status text not null,
    created_at timestamptz not null,
    created_by uuid not null,
    updated_at timestamptz not null,
    updated_by uuid not null,
    row_version bigint not null default 1,
    constraint pk_employee_letters primary key (id),
    constraint uq_employee_letters_company_id_letter_no unique (company_id, letter_no),
    constraint ck_employee_letters_letter_type_code check (length(letter_type) between 1 and 40 and letter_type = btrim(letter_type)),
    constraint ck_employee_letters_status check (status in ('draft', 'pending_approval', 'approved', 'issued', 'acknowledged', 'cancelled'))
);
create index if not exists ix_employee_letters_employment_id on hrm.employee_letters (employment_id); -- listed in the data design
create index if not exists ix_employee_letters_company_id_employment_id on hrm.employee_letters (company_id, employment_id); -- foreign key fk_employee_letters_employment_id
create index if not exists ix_employee_letters_template_id on hrm.employee_letters (template_id); -- foreign key fk_employee_letters_template_id
create index if not exists ix_employee_letters_company_id_generated_document_id on hrm.employee_letters (company_id, generated_document_id); -- foreign key fk_employee_letters_generated_document_id
create index if not exists ix_employee_letters_company_id_workflow_instance_id on hrm.employee_letters (company_id, workflow_instance_id); -- foreign key fk_employee_letters_workflow_instance_id

-- hrm.employment_assignments: Effective-dated job details; every change closes the current row and opens a new one [EMP-02, EMP-03, POS-01]
create table if not exists hrm.employment_assignments (
    id uuid not null,
    company_id uuid not null,
    employment_id uuid not null,
    event_id uuid not null,
    org_unit_id uuid not null,
    position_id uuid,
    title text not null,
    grade_id uuid,
    branch_id uuid not null,
    location_id uuid,
    manager_employment_id uuid,
    pay_group_id uuid,
    cost_allocation jsonb not null,
    fte numeric(9,6) not null default 1,
    work_schedule text,
    is_acting boolean not null default false,
    valid_from date not null,
    valid_to date,
    created_at timestamptz not null,
    created_by uuid not null,
    updated_at timestamptz not null,
    updated_by uuid not null,
    row_version bigint not null default 1,
    constraint pk_employment_assignments primary key (id),
    constraint ck_employment_assignments_work_schedule_code check (length(work_schedule) between 1 and 40 and work_schedule = btrim(work_schedule)),
    constraint ck_employment_assignments_valid_to check (valid_to is null or valid_to > valid_from),
    constraint ex_employment_assignments_employment_id exclude using gist (employment_id with =, daterange(valid_from, valid_to, '[)') with &&)
);
create index if not exists ix_employment_assignments_employment_id_valid_from on hrm.employment_assignments (employment_id, valid_from); -- listed in the data design
create index if not exists ix_employment_assignments_org_unit_id on hrm.employment_assignments (org_unit_id); -- listed in the data design
create index if not exists ix_employment_assignments_manager_employment_id on hrm.employment_assignments (manager_employment_id); -- listed in the data design
create index if not exists ix_employment_assignments_company_id on hrm.employment_assignments (company_id); -- foreign key fk_employment_assignments_company_id
create index if not exists ix_employment_assignments_company_id_employment_id on hrm.employment_assignments (company_id, employment_id); -- foreign key fk_employment_assignments_employment_id
create index if not exists ix_employment_assignments_company_id_event_id on hrm.employment_assignments (company_id, event_id); -- foreign key fk_employment_assignments_event_id
create index if not exists ix_employment_assignments_company_id_org_unit_id on hrm.employment_assignments (company_id, org_unit_id); -- foreign key fk_employment_assignments_org_unit_id
create index if not exists ix_employment_assignments_company_id_position_id on hrm.employment_assignments (company_id, position_id); -- foreign key fk_employment_assignments_position_id
create index if not exists ix_employment_assignments_company_id_grade_id on hrm.employment_assignments (company_id, grade_id); -- foreign key fk_employment_assignments_grade_id
create index if not exists ix_employment_assignments_company_id_branch_id on hrm.employment_assignments (company_id, branch_id); -- foreign key fk_employment_assignments_branch_id
create index if not exists ix_employment_assignments_company_id_location_id on hrm.employment_assignments (company_id, location_id); -- foreign key fk_employment_assignments_location_id
create index if not exists ix_employment_assignments_company_id_manager_employment_id on hrm.employment_assignments (company_id, manager_employment_id); -- foreign key fk_employment_assignments_manager_employment_id
create index if not exists ix_employment_assignments_company_id_pay_group_id on hrm.employment_assignments (company_id, pay_group_id); -- foreign key fk_employment_assignments_pay_group_id

-- hrm.employment_events: Why something changed (hire, promotion, transfer ... termination) with reason code [EMP-03, EMP-11, FR-XM-30]
create table if not exists hrm.employment_events (
    id uuid not null,
    company_id uuid not null,
    employment_id uuid not null,
    kind text not null,
    reason_code text not null,
    effective_date date not null,
    notes text,
    carry_over jsonb,
    workflow_instance_id uuid,
    letter_document_id uuid,
    status text not null,
    created_at timestamptz not null,
    created_by uuid not null,
    updated_at timestamptz not null,
    updated_by uuid not null,
    row_version bigint not null default 1,
    constraint pk_employment_events primary key (id),
    constraint uq_employment_events_company_id_id unique (company_id, id),
    constraint ck_employment_events_kind check (kind in ('hire', 'rehire', 'promotion', 'demotion', 'transfer', 'grade_change', 'acting', 'secondment', 'confirmation', 'probation_extension', 'salary_revision', 'separation', 'data_correction')),
    constraint ck_employment_events_reason_code_code check (length(reason_code) between 1 and 40 and reason_code = btrim(reason_code)),
    constraint ck_employment_events_status check (status in ('draft', 'pending_approval', 'approved', 'effective', 'cancelled'))
);
create index if not exists ix_employment_events_employment_id_effective_date on hrm.employment_events (employment_id, effective_date); -- listed in the data design
create index if not exists ix_employment_events_company_id_employment_id on hrm.employment_events (company_id, employment_id); -- foreign key fk_employment_events_employment_id
create index if not exists ix_employment_events_company_id_workflow_instance_id on hrm.employment_events (company_id, workflow_instance_id); -- foreign key fk_employment_events_workflow_instance_id
create index if not exists ix_employment_events_company_id_letter_document_id on hrm.employment_events (company_id, letter_document_id); -- foreign key fk_employment_events_letter_document_id

-- hrm.employment_statutory_registrations: Per-employee applicability and registration for EOBI, provincial social security and provident fund [PAY-20, CPL-02]
create table if not exists hrm.employment_statutory_registrations (
    id uuid not null,
    company_id uuid not null,
    employment_id uuid not null,
    scheme text not null,
    is_applicable boolean not null default false,
    exemption_reason text,
    registration_no bytea,
    registration_no_hmac bytea,
    valid_from date not null,
    valid_to date,
    created_at timestamptz not null,
    created_by uuid not null,
    updated_at timestamptz not null,
    updated_by uuid not null,
    row_version bigint not null default 1,
    constraint pk_employment_statutory_registrations primary key (id),
    constraint ck_employment_statutory_registrations_scheme_code check (length(scheme) between 1 and 40 and scheme = btrim(scheme)),
    constraint ck_employment_statutory_registrations_valid_to check (valid_to is null or valid_to > valid_from),
    constraint ex_employment_statutory_registrations_employment_id_scheme exclude using gist (employment_id with =, scheme with =, daterange(valid_from, valid_to, '[)') with &&)
);
create index if not exists ix_employment_statutory_registrations_company_id on hrm.employment_statutory_registrations (company_id); -- foreign key fk_employment_statutory_registrations_company_id
create index if not exists ix_employment_statutory_registrations_company_id_employment_id on hrm.employment_statutory_registrations (company_id, employment_id); -- foreign key fk_employment_statutory_registrations_employment_id

-- hrm.employments: One employment of a person with one company; transfers between companies create a new linked row (FR-XM-30) [EMP-02, EMP-04, EMP-07, EMP-15, EMP-17, FR-XM-30]
create table if not exists hrm.employments (
    id uuid not null,
    company_id uuid not null,
    person_id uuid not null,
    employee_no text not null,
    employee_type text not null,
    joining_date date not null,
    service_start_date date not null,
    confirmation_date date,
    expected_end_date date,
    separation_date date,
    previous_employment_id uuid,
    user_ref uuid,
    is_primary boolean not null default false,
    status text not null,
    custom jsonb not null default '{}'::jsonb,
    created_at timestamptz not null,
    created_by uuid not null,
    updated_at timestamptz not null,
    updated_by uuid not null,
    row_version bigint not null default 1,
    constraint pk_employments primary key (id),
    constraint uq_employments_company_id_id unique (company_id, id),
    constraint ck_employments_employee_type_code check (length(employee_type) between 1 and 40 and employee_type = btrim(employee_type)),
    constraint ck_employments_status check (status in ('pre_joining', 'active', 'on_notice', 'separated', 'cancelled'))
);
create unique index if not exists uq_employments_company_id_employee_no on hrm.employments (company_id, lower(employee_no));
create unique index if not exists uq_employments_person_id on hrm.employments (person_id) where (is_primary and status in ('pre_joining','active','on_notice'));
create index if not exists ix_employments_person_id on hrm.employments (person_id); -- listed in the data design
create index if not exists ix_employments_company_id_status on hrm.employments (company_id, status); -- listed in the data design
create index if not exists ix_employments_company_id_previous_employment_id on hrm.employments (company_id, previous_employment_id); -- foreign key fk_employments_previous_employment_id

-- hrm.expense_categories: ExpenseCategories [EXP-01]
create table if not exists hrm.expense_categories (
    id uuid not null,
    company_id uuid not null,
    code text not null,
    name_i18n jsonb not null,
    policy_id uuid,
    requires_receipt boolean not null default false,
    reimbursement_component_id uuid,
    is_active boolean not null default true,
    is_deleted boolean not null default false,
    deleted_at timestamptz,
    deleted_by uuid,
    created_at timestamptz not null,
    created_by uuid not null,
    updated_at timestamptz not null,
    updated_by uuid not null,
    row_version bigint not null default 1,
    constraint pk_expense_categories primary key (id),
    constraint uq_expense_categories_company_id_id unique (company_id, id),
    constraint ck_expense_categories_code_code check (length(code) between 1 and 40 and code = btrim(code)),
    constraint ck_expense_categories_name_i18n_object check (jsonb_typeof(name_i18n) = 'object')
);
create unique index if not exists uq_expense_categories_company_id_code on hrm.expense_categories (company_id, lower(code)) where (not is_deleted);
create index if not exists ix_expense_categories_company_id_policy_id on hrm.expense_categories (company_id, policy_id); -- foreign key fk_expense_categories_policy_id
create index if not exists ix_expense_categories_company_id_reimbursement_component_id on hrm.expense_categories (company_id, reimbursement_component_id); -- foreign key fk_expense_categories_reimbursement_component_id

-- hrm.expense_claim_lines: ExpenseClaimLines [EXP-02, EXP-03]
create table if not exists hrm.expense_claim_lines (
