    created_at timestamptz not null,
    created_by uuid not null,
    updated_at timestamptz not null,
    updated_by uuid not null,
    row_version bigint not null default 1,
    constraint pk_expense_claim_lines primary key (id)
);
create index if not exists ix_expense_claim_lines_claim_id on hrm.expense_claim_lines (claim_id); -- listed in the data design
create index if not exists ix_expense_claim_lines_receipt_hash on hrm.expense_claim_lines (receipt_hash); -- listed in the data design
create index if not exists ix_expense_claim_lines_company_id on hrm.expense_claim_lines (company_id); -- foreign key fk_expense_claim_lines_company_id
create index if not exists ix_expense_claim_lines_company_id_claim_id on hrm.expense_claim_lines (company_id, claim_id); -- foreign key fk_expense_claim_lines_claim_id
create index if not exists ix_expense_claim_lines_company_id_category_id on hrm.expense_claim_lines (company_id, category_id); -- foreign key fk_expense_claim_lines_category_id
create index if not exists ix_expense_claim_lines_company_id_receipt_file_id on hrm.expense_claim_lines (company_id, receipt_file_id); -- foreign key fk_expense_claim_lines_receipt_file_id

-- hrm.expense_claims: ExpenseClaims [EXP-02, EXP-05, EXP-06]
create table if not exists hrm.expense_claims (
    id uuid not null,
    company_id uuid not null,
    branch_id uuid,
    claim_no text not null,
    employment_id uuid not null,
    currency_code char(3) not null,
    total_amount numeric(19,4) not null,
    reimburse_via text not null,
    pay_input_id uuid,
    workflow_instance_id uuid,
    status text not null,
    created_at timestamptz not null,
    created_by uuid not null,
    updated_at timestamptz not null,
    updated_by uuid not null,
    row_version bigint not null default 1,
    constraint pk_expense_claims primary key (id),
    constraint uq_expense_claims_company_id_claim_no unique (company_id, claim_no),
    constraint uq_expense_claims_company_id_id unique (company_id, id),
    constraint ck_expense_claims_reimburse_via check (reimburse_via in ('payroll', 'payment_batch')),
    constraint ck_expense_claims_status check (status in ('draft', 'submitted', 'approved', 'rejected', 'reimbursed', 'cancelled'))
);
create index if not exists ix_expense_claims_company_id_branch_id on hrm.expense_claims (company_id, branch_id); -- foreign key fk_expense_claims_branch_id
create index if not exists ix_expense_claims_company_id_employment_id on hrm.expense_claims (company_id, employment_id); -- foreign key fk_expense_claims_employment_id
create index if not exists ix_expense_claims_company_id_pay_input_id on hrm.expense_claims (company_id, pay_input_id); -- foreign key fk_expense_claims_pay_input_id
create index if not exists ix_expense_claims_company_id_workflow_instance_id on hrm.expense_claims (company_id, workflow_instance_id); -- foreign key fk_expense_claims_workflow_instance_id

-- hrm.final_settlement_lines: FinalSettlementLines [PAY-26, LND-06, CMP-04]
create table if not exists hrm.final_settlement_lines (
    id uuid not null,
    company_id uuid not null,
    settlement_id uuid not null,
    kind text not null,
    component_id uuid,
    amount numeric(19,4) not null,
    basis jsonb not null,
    created_at timestamptz not null,
    created_by uuid not null,
    updated_at timestamptz not null,
    updated_by uuid not null,
    row_version bigint not null default 1,
    constraint pk_final_settlement_lines primary key (id),
    constraint ck_final_settlement_lines_kind check (kind in ('pending_salary', 'leave_encashment', 'gratuity', 'notice_pay', 'notice_recovery', 'loan_recovery', 'advance_recovery', 'bond_recovery', 'bonus', 'tax_adjustment', 'pf_payout', 'other'))
);
create index if not exists ix_final_settlement_lines_company_id on hrm.final_settlement_lines (company_id); -- foreign key fk_final_settlement_lines_company_id
create index if not exists ix_final_settlement_lines_company_id_settlement_id on hrm.final_settlement_lines (company_id, settlement_id); -- foreign key fk_final_settlement_lines_settlement_id
create index if not exists ix_final_settlement_lines_company_id_component_id on hrm.final_settlement_lines (company_id, component_id); -- foreign key fk_final_settlement_lines_component_id

-- hrm.final_settlements: FinalSettlements [PAY-26, PAY-27, ONB-17, FR-XM-29]
create table if not exists hrm.final_settlements (
    id uuid not null,
    company_id uuid not null,
    employment_id uuid not null,
    separation_id uuid not null,
    pay_run_id uuid,
    clearance_status text not null,
    open_items jsonb not null,
    net_amount numeric(19,4),
    currency_code char(3) not null,
    statement_document_id uuid,
    acknowledged_at timestamptz,
    workflow_instance_id uuid,
    status text not null,
    created_at timestamptz not null,
    created_by uuid not null,
    updated_at timestamptz not null,
    updated_by uuid not null,
    row_version bigint not null default 1,
    constraint pk_final_settlements primary key (id),
    constraint uq_final_settlements_company_id_id unique (company_id, id),
    constraint ck_final_settlements_clearance_status check (clearance_status in ('pending', 'cleared', 'waived')),
    constraint ck_final_settlements_status check (status in ('draft', 'calculated', 'blocked', 'approved', 'paid', 'cancelled')),
    constraint ck_final_settlements_paid_needs_run check (status <> 'paid' or pay_run_id is not null)
);
create unique index if not exists uq_final_settlements_employment_id on hrm.final_settlements (employment_id) where (status <> 'cancelled');
create index if not exists ix_final_settlements_company_id_employment_id on hrm.final_settlements (company_id, employment_id); -- foreign key fk_final_settlements_employment_id
create index if not exists ix_final_settlements_company_id_separation_id on hrm.final_settlements (company_id, separation_id); -- foreign key fk_final_settlements_separation_id
create index if not exists ix_final_settlements_company_id_pay_run_id on hrm.final_settlements (company_id, pay_run_id); -- foreign key fk_final_settlements_pay_run_id
create index if not exists ix_final_settlements_company_id_statement_document_id on hrm.final_settlements (company_id, statement_document_id); -- foreign key fk_final_settlements_statement_document_id
create index if not exists ix_final_settlements_company_id_workflow_instance_id on hrm.final_settlements (company_id, workflow_instance_id); -- foreign key fk_final_settlements_workflow_instance_id

-- hrm.form_definitions: Configurable forms for appraisals and probation reviews (PRF-03, ONB-12) [PRF-03, ONB-12]
create table if not exists hrm.form_definitions (
    id uuid not null,
    company_id uuid not null,
    code text not null,
    name_i18n jsonb not null,
    purpose text not null,
    active_version_id uuid,
    is_active boolean not null default true,
    is_deleted boolean not null default false,
    deleted_at timestamptz,
    deleted_by uuid,
    created_at timestamptz not null,
    created_by uuid not null,
    updated_at timestamptz not null,
    updated_by uuid not null,
    row_version bigint not null default 1,
    constraint pk_form_definitions primary key (id),
    constraint uq_form_definitions_company_id_id unique (company_id, id),
    constraint ck_form_definitions_code_code check (length(code) between 1 and 40 and code = btrim(code)),
    constraint ck_form_definitions_name_i18n_object check (jsonb_typeof(name_i18n) = 'object'),
    constraint ck_form_definitions_purpose check (purpose in ('appraisal', 'probation_review', 'goal_review', 'custom'))
);
create unique index if not exists uq_form_definitions_company_id_code on hrm.form_definitions (company_id, lower(code)) where (not is_deleted);
create index if not exists ix_form_definitions_id_active_version_id on hrm.form_definitions (id, active_version_id); -- foreign key fk_form_definitions_active_version_id

-- hrm.form_responses: FormResponses [PRF-03, PRF-04, ONB-12]
create table if not exists hrm.form_responses (
    id uuid not null,
    company_id uuid not null,
    form_version_id uuid not null,
    subject_employment_id uuid not null,
    respondent_employment_id uuid,
    context_type text not null,
    context_id uuid not null,
    answers jsonb not null,
    score numeric(19,6),
    submitted_at timestamptz,
    status text not null,
    created_at timestamptz not null,
    created_by uuid not null,
    updated_at timestamptz not null,
    updated_by uuid not null,
    row_version bigint not null default 1,
    constraint pk_form_responses primary key (id),
    constraint uq_form_responses_company_id_id unique (company_id, id),
    constraint ck_form_responses_status check (status in ('draft', 'submitted', 'locked'))
);
create index if not exists ix_form_responses_context_type_context_id on hrm.form_responses (context_type, context_id); -- listed in the data design
create index if not exists ix_form_responses_subject_employment_id on hrm.form_responses (subject_employment_id); -- listed in the data design
create index if not exists ix_form_responses_form_version_id on hrm.form_responses (form_version_id); -- foreign key fk_form_responses_form_version_id
create index if not exists ix_form_responses_company_id_subject_employment_id on hrm.form_responses (company_id, subject_employment_id); -- foreign key fk_form_responses_subject_employment_id
create index if not exists ix_form_responses_company_id_respondent_employment_id on hrm.form_responses (company_id, respondent_employment_id); -- foreign key fk_form_responses_respondent_employment_id

-- hrm.form_versions: FormVersions [PRF-03]
