-- hrm.goal_updates: GoalUpdates [PRF-02]
create table if not exists hrm.goal_updates (
    id uuid not null,
    company_id uuid not null,
    goal_id uuid not null,
    progress_pct numeric(9,6),
    actual jsonb,
    comment text,
    created_at timestamptz not null,
    created_by uuid not null,
    constraint pk_goal_updates primary key (id)
);
create index if not exists ix_goal_updates_goal_id_created_at on hrm.goal_updates (goal_id, created_at); -- listed in the data design
create index if not exists ix_goal_updates_company_id on hrm.goal_updates (company_id); -- foreign key fk_goal_updates_company_id
create index if not exists ix_goal_updates_company_id_goal_id on hrm.goal_updates (company_id, goal_id); -- foreign key fk_goal_updates_goal_id
create or replace trigger tg_goal_updates_append_only before update or delete on hrm.goal_updates for each row execute function hrm.tg_refuse_change();
create or replace trigger tg_goal_updates_no_truncate before truncate on hrm.goal_updates for each statement execute function hrm.tg_refuse_change();

-- hrm.goals: Goals [PRF-02]
create table if not exists hrm.goals (
    id uuid not null,
    company_id uuid not null,
    cycle_id uuid,
    owner_employment_id uuid,
    org_unit_id uuid,
    parent_goal_id uuid,
    framework text not null,
    title text not null,
    description text,
    weight numeric(9,6),
    target jsonb not null,
    actual jsonb,
    due_date date,
    status text not null,
    created_at timestamptz not null,
    created_by uuid not null,
    updated_at timestamptz not null,
    updated_by uuid not null,
    row_version bigint not null default 1,
    constraint pk_goals primary key (id),
    constraint uq_goals_company_id_id unique (company_id, id),
    constraint ck_goals_framework check (framework in ('kpi', 'okr', 'scorecard')),
    constraint ck_goals_status check (status in ('draft', 'agreed', 'in_progress', 'achieved', 'partially_achieved', 'missed', 'cancelled'))
);
