create index if not exists ix_goals_company_id_org_unit_id on hrm.goals (company_id, org_unit_id); -- foreign key fk_goals_org_unit_id
create index if not exists ix_goals_company_id_parent_goal_id on hrm.goals (company_id, parent_goal_id); -- foreign key fk_goals_parent_goal_id

-- hrm.grades: Grades [POS-06]
