    updated_at timestamptz not null,
    updated_by uuid not null,
    row_version bigint not null default 1,
    constraint pk_grades primary key (id),
    constraint uq_grades_company_id_id unique (company_id, id),
    constraint ck_grades_code_code check (length(code) between 1 and 40 and code = btrim(code)),
    constraint ck_grades_name_i18n_object check (jsonb_typeof(name_i18n) = 'object')
);
create unique index if not exists uq_grades_company_id_code on hrm.grades (company_id, lower(code)) where (not is_deleted);

-- hrm.headcount_budgets: Headcount-based model (POS-01) — sanctioned strength per unit and grade [POS-01, POS-03]
create table if not exists hrm.headcount_budgets (
    id uuid not null,
    company_id uuid not null,
    org_unit_id uuid not null,
    grade_id uuid,
    sanctioned_count integer not null,
    valid_from date not null,
    valid_to date,
    created_at timestamptz not null,
    created_by uuid not null,
    updated_at timestamptz not null,
    updated_by uuid not null,
    row_version bigint not null default 1,
    constraint pk_headcount_budgets primary key (id),
    constraint ck_headcount_budgets_valid_to check (valid_to is null or valid_to > valid_from),
    constraint ex_headcount_budgets_org_unit_id_grade_id exclude using gist (org_unit_id with =, (coalesce(grade_id, '00000000-0000-0000-0000-000000000000'::uuid)) with =, daterange(valid_from, valid_to, '[)') with &&)
);
create index if not exists ix_headcount_budgets_company_id on hrm.headcount_budgets (company_id); -- foreign key fk_headcount_budgets_company_id
create index if not exists ix_headcount_budgets_company_id_org_unit_id on hrm.headcount_budgets (company_id, org_unit_id); -- foreign key fk_headcount_budgets_org_unit_id
create index if not exists ix_headcount_budgets_company_id_grade_id on hrm.headcount_budgets (company_id, grade_id); -- foreign key fk_headcount_budgets_grade_id

