-- hrm.loans: Loans [LON-01, LON-02, LON-03, LON-05]
create table if not exists hrm.loans (
    id uuid not null,
    company_id uuid not null,
    loan_no text not null,
    employment_id uuid not null,
    loan_type_id uuid not null,
    principal numeric(19,4) not null,
    currency_code char(3) not null,
    interest_rate numeric(9,6) not null default 0,
    installments integer not null,
    start_period_id uuid,
    guarantor_employment_id uuid,
    disbursed_on date,
    workflow_instance_id uuid,
    status text not null,
    created_at timestamptz not null,
    created_by uuid not null,
    updated_at timestamptz not null,
    updated_by uuid not null,
    row_version bigint not null default 1,
    constraint pk_loans primary key (id),
    constraint uq_loans_company_id_loan_no unique (company_id, loan_no),
    constraint uq_loans_company_id_id unique (company_id, id),
    constraint ck_loans_status check (status in ('applied', 'approved', 'rejected', 'disbursed', 'active', 'settled', 'written_off', 'cancelled'))
);
create index if not exists ix_loans_company_id_employment_id on hrm.loans (company_id, employment_id); -- foreign key fk_loans_employment_id
create index if not exists ix_loans_company_id_loan_type_id on hrm.loans (company_id, loan_type_id); -- foreign key fk_loans_loan_type_id
create index if not exists ix_loans_company_id_start_period_id on hrm.loans (company_id, start_period_id); -- foreign key fk_loans_start_period_id
create index if not exists ix_loans_company_id_guarantor_employment_id on hrm.loans (company_id, guarantor_employment_id); -- foreign key fk_loans_guarantor_employment_id
create index if not exists ix_loans_company_id_workflow_instance_id on hrm.loans (company_id, workflow_instance_id); -- foreign key fk_loans_workflow_instance_id

-- hrm.mandatory_training_rules: MandatoryTrainingRules [LND-04]
create table if not exists hrm.mandatory_training_rules (
    id uuid not null,
    company_id uuid not null,
    course_id uuid not null,
    applies_rule jsonb not null,
    due_within_days integer not null,
    recurrence_months integer,
    status text not null,
    created_at timestamptz not null,
    created_by uuid not null,
    updated_at timestamptz not null,
    updated_by uuid not null,
    row_version bigint not null default 1,
    constraint pk_mandatory_training_rules primary key (id),
    constraint uq_mandatory_training_rules_company_id_id unique (company_id, id),
    constraint ck_mandatory_training_rules_status check (status in ('active', 'inactive'))
);
create index if not exists ix_mandatory_training_rules_company_id_course_id on hrm.mandatory_training_rules (company_id, course_id); -- foreign key fk_mandatory_training_rules_course_id

-- hrm.nominations: Nominees per scheme (provident fund, gratuity, insurance plan) [CMP-04, CMP-05, PAY-26]
create table if not exists hrm.nominations (
    id uuid not null,
    person_id uuid not null,
    scheme text not null,
    relation_id uuid not null,
    share numeric(9,6) not null,
    valid_from date not null,
    valid_to date,
    created_at timestamptz not null,
    created_by uuid not null,
    updated_at timestamptz not null,
    updated_by uuid not null,
    row_version bigint not null default 1,
    constraint pk_nominations primary key (id),
    constraint ck_nominations_scheme_code check (length(scheme) between 1 and 40 and scheme = btrim(scheme)),
    constraint ck_nominations_valid_to check (valid_to is null or valid_to > valid_from),
    constraint ex_nominations_person_id_scheme_relation_id exclude using gist (person_id with =, scheme with =, relation_id with =, daterange(valid_from, valid_to, '[)') with &&)
);
create index if not exists ix_nominations_person_id on hrm.nominations (person_id); -- foreign key fk_nominations_person_id
create index if not exists ix_nominations_relation_id on hrm.nominations (relation_id); -- foreign key fk_nominations_relation_id

-- hrm.outbox_messages: Events written in the business transaction; the dispatcher publishes them (spec 03 section 7.5)
create table if not exists hrm.outbox_messages (
    id uuid not null,
    occurred_at timestamptz not null,
    event_type text not null,
    aggregate_type text not null,
    aggregate_id uuid not null,
    payload jsonb not null,
    headers jsonb not null default '{}'::jsonb,
    published_at timestamptz,
    constraint pk_outbox_messages primary key (id)
);
create index if not exists ix_outbox_messages_occurred_at_unpublished on hrm.outbox_messages (occurred_at) where (published_at is null); -- dispatcher reads unpublished messages in order

-- hrm.overtime_entries: OvertimeEntries [ATT-12, LVE-08]
create table if not exists hrm.overtime_entries (
    id uuid not null,
    company_id uuid not null,
    employment_id uuid not null,
    work_date date not null,
    day_type text not null,
    minutes integer not null,
    approved_minutes integer,
    rate_multiplier numeric(19,10) not null,
    pay_input_id uuid,
    attendance_day_id uuid,
    comp_off_entry_id uuid,
    workflow_instance_id uuid,
    status text not null,
    created_at timestamptz not null,
    created_by uuid not null,
    updated_at timestamptz not null,
    updated_by uuid not null,
    row_version bigint not null default 1,
    constraint pk_overtime_entries primary key (id),
    constraint ck_overtime_entries_day_type check (day_type in ('working', 'weekly_off', 'holiday')),
    constraint ck_overtime_entries_status check (status in ('calculated', 'submitted', 'approved', 'rejected', 'paid', 'converted_to_comp_off'))
);
create unique index if not exists uq_overtime_entries_employment_id_work_date on hrm.overtime_entries (employment_id, work_date) where (status <> 'rejected');
create index if not exists ix_overtime_entries_employment_id_work_date on hrm.overtime_entries (employment_id, work_date); -- listed in the data design
create index if not exists ix_overtime_entries_company_id on hrm.overtime_entries (company_id); -- foreign key fk_overtime_entries_company_id
create index if not exists ix_overtime_entries_company_id_employment_id on hrm.overtime_entries (company_id, employment_id); -- foreign key fk_overtime_entries_employment_id
create index if not exists ix_overtime_entries_company_id_pay_input_id on hrm.overtime_entries (company_id, pay_input_id); -- foreign key fk_overtime_entries_pay_input_id
create index if not exists ix_overtime_entries_company_id_attendance_day_id_work_date on hrm.overtime_entries (company_id, attendance_day_id, work_date); -- foreign key fk_overtime_entries_attendance_day_id
create index if not exists ix_overtime_entries_company_id_comp_off_entry_id on hrm.overtime_entries (company_id, comp_off_entry_id); -- foreign key fk_overtime_entries_comp_off_entry_id
create index if not exists ix_overtime_entries_company_id_workflow_instance_id on hrm.overtime_entries (company_id, workflow_instance_id); -- foreign key fk_overtime_entries_workflow_instance_id

-- hrm.parallel_run_lines: ParallelRunLines [PAY-35]
create table if not exists hrm.parallel_run_lines (
    id uuid not null,
    company_id uuid not null,
    parallel_run_id uuid not null,
    employment_id uuid,
    legacy_employee_no text not null,
    component_code text not null,
    legacy_amount numeric(19,4),
    new_amount numeric(19,4),
    difference numeric(19,4) not null,
    explanation text,
    created_at timestamptz not null,
    created_by uuid not null,
    updated_at timestamptz not null,
    updated_by uuid not null,
    row_version bigint not null default 1,
    constraint pk_parallel_run_lines primary key (id),
    constraint ck_parallel_run_lines_component_code_code check (length(component_code) between 1 and 40 and component_code = btrim(component_code))
);
create index if not exists ix_parallel_run_lines_parallel_run_id_employment_id on hrm.parallel_run_lines (parallel_run_id, employment_id); -- listed in the data design
create index if not exists ix_parallel_run_lines_company_id on hrm.parallel_run_lines (company_id); -- foreign key fk_parallel_run_lines_company_id
create index if not exists ix_parallel_run_lines_company_id_parallel_run_id on hrm.parallel_run_lines (company_id, parallel_run_id); -- foreign key fk_parallel_run_lines_parallel_run_id
create index if not exists ix_parallel_run_lines_company_id_employment_id on hrm.parallel_run_lines (company_id, employment_id); -- foreign key fk_parallel_run_lines_employment_id

-- hrm.parallel_runs: Compare a pay run with the customer's legacy payroll results before go-live [PAY-35]
create table if not exists hrm.parallel_runs (
    id uuid not null,
    company_id uuid not null,
    pay_run_id uuid not null,
    import_batch_id uuid not null,
    tolerance numeric(19,4) not null,
    summary jsonb,
    signed_off_by uuid,
    currency_code char(3) not null,
    status text not null,
    created_at timestamptz not null,
    created_by uuid not null,
    updated_at timestamptz not null,
    updated_by uuid not null,
    row_version bigint not null default 1,
    constraint pk_parallel_runs primary key (id),
    constraint uq_parallel_runs_company_id_id unique (company_id, id),
    constraint ck_parallel_runs_status check (status in ('imported', 'compared', 'signed_off'))
);
create index if not exists ix_parallel_runs_company_id_pay_run_id on hrm.parallel_runs (company_id, pay_run_id); -- foreign key fk_parallel_runs_pay_run_id
create index if not exists ix_parallel_runs_company_id_import_batch_id on hrm.parallel_runs (company_id, import_batch_id); -- foreign key fk_parallel_runs_import_batch_id

-- hrm.pay_component_versions: Calculation definition of a component, effective-dated; runs record the version used [PAY-02, PAY-03, PAY-05, PAY-18, PAY-31]
create table if not exists hrm.pay_component_versions (
    id uuid not null,
    component_id uuid not null,
    method text not null,
    formula text,
    base_component_ids uuid[] not null default '{}',
    statutory_table_code text,
    pro_rata_rule text not null,
    statutory_flags jsonb not null,
    tax_treatment text,
    valid_from date not null,
    valid_to date,
    created_at timestamptz not null,
    created_by uuid not null,
    updated_at timestamptz not null,
    updated_by uuid not null,
    row_version bigint not null default 1,
    constraint pk_pay_component_versions primary key (id),
    constraint ck_pay_component_versions_method check (method in ('fixed', 'percent_of', 'formula', 'table_lookup', 'per_day', 'per_hour', 'attendance_linked', 'manual')),
    constraint ck_pay_component_versions_statutory_table_code_code check (length(statutory_table_code) between 1 and 40 and statutory_table_code = btrim(statutory_table_code)),
    constraint ck_pay_component_versions_pro_rata_rule check (pro_rata_rule in ('none', 'calendar_days', 'working_days', 'fixed_30', 'custom')),
    constraint ck_pay_component_versions_tax_treatment_code check (length(tax_treatment) between 1 and 40 and tax_treatment = btrim(tax_treatment)),
    constraint ck_pay_component_versions_valid_to check (valid_to is null or valid_to > valid_from),
    constraint ex_pay_component_versions_component_id exclude using gist (component_id with =, daterange(valid_from, valid_to, '[)') with &&)
);
create index if not exists ix_pay_component_versions_component_id on hrm.pay_component_versions (component_id); -- foreign key fk_pay_component_versions_component_id

-- hrm.pay_components: PayComponents [PAY-02, PAY-03, PAY-05, PAY-08, PAY-18, CMP-03]
create table if not exists hrm.pay_components (
    id uuid not null,
    company_id uuid not null,
    code text not null,
    name_i18n jsonb not null,
    kind text not null,
    payslip_order integer not null,
    is_recurring boolean not null default false,
    is_one_time_allowed boolean not null default false,
    source text not null,
    is_active boolean not null default true,
    is_deleted boolean not null default false,
    deleted_at timestamptz,
    deleted_by uuid,
    created_at timestamptz not null,
    created_by uuid not null,
    updated_at timestamptz not null,
    updated_by uuid not null,
    row_version bigint not null default 1,
    constraint pk_pay_components primary key (id),
    constraint uq_pay_components_company_id_id unique (company_id, id),
    constraint ck_pay_components_code_code check (length(code) between 1 and 40 and code = btrim(code)),
    constraint ck_pay_components_name_i18n_object check (jsonb_typeof(name_i18n) = 'object'),
    constraint ck_pay_components_kind check (kind in ('earning', 'deduction', 'employer_contribution', 'reimbursement', 'informational')),
    constraint ck_pay_components_source check (source in ('pack', 'tenant'))
);
create unique index if not exists uq_pay_components_company_id_code on hrm.pay_components (company_id, lower(code)) where (not is_deleted);

-- hrm.pay_groups: PayGroups [PAY-01, PAY-13]
create table if not exists hrm.pay_groups (
    id uuid not null,
    company_id uuid not null,
    code text not null,
    name_i18n jsonb not null,
    frequency text not null,
    currency_code char(3) not null,
    tax_year_start_month integer not null,
    cut_off_day integer,
    payment_day integer,
    company_bank_account_id uuid,
    approval_threshold numeric(19,4),
    is_active boolean not null default true,
    is_deleted boolean not null default false,
    deleted_at timestamptz,
    deleted_by uuid,
    created_at timestamptz not null,
    created_by uuid not null,
    updated_at timestamptz not null,
    updated_by uuid not null,
    row_version bigint not null default 1,
    constraint pk_pay_groups primary key (id),
    constraint uq_pay_groups_company_id_id unique (company_id, id),
    constraint ck_pay_groups_code_code check (length(code) between 1 and 40 and code = btrim(code)),
    constraint ck_pay_groups_name_i18n_object check (jsonb_typeof(name_i18n) = 'object'),
    constraint ck_pay_groups_frequency check (frequency in ('monthly', 'semi_monthly', 'bi_weekly', 'weekly'))
);
create unique index if not exists uq_pay_groups_company_id_code on hrm.pay_groups (company_id, lower(code)) where (not is_deleted);
create index if not exists ix_pay_groups_currency_code on hrm.pay_groups (currency_code); -- foreign key fk_pay_groups_currency_code
create index if not exists ix_pay_groups_company_id_company_bank_account_id on hrm.pay_groups (company_id, company_bank_account_id); -- foreign key fk_pay_groups_company_bank_account_id

-- hrm.pay_inputs: One-time inputs to a period (bonus, incentive, deduction, adjustment, imported file rows) [PAY-07, PAY-08]
create table if not exists hrm.pay_inputs (
    id uuid not null,
    company_id uuid not null,
    employment_id uuid not null,
    pay_period_id uuid not null,
    component_id uuid not null,
    amount numeric(19,4),
    currency_code char(3) not null,
    units numeric(19,6),
    source_type text not null,
    source_id uuid,
    consumed_by_run_id uuid,
    import_batch_id uuid,
    status text not null,
    created_at timestamptz not null,
    created_by uuid not null,
    updated_at timestamptz not null,
    updated_by uuid not null,
    row_version bigint not null default 1,
    constraint pk_pay_inputs primary key (id),
    constraint uq_pay_inputs_company_id_id unique (company_id, id),
    constraint ck_pay_inputs_status check (status in ('pending', 'consumed', 'cancelled'))
);
create unique index if not exists uq_pay_inputs_source_type_source_id_component_id on hrm.pay_inputs (source_type, source_id, component_id) nulls not distinct where (status <> 'cancelled' and source_id is not null);
create index if not exists ix_pay_inputs_employment_id_pay_period_id on hrm.pay_inputs (employment_id, pay_period_id); -- listed in the data design
create index if not exists ix_pay_inputs_company_id_employment_id on hrm.pay_inputs (company_id, employment_id); -- foreign key fk_pay_inputs_employment_id
create index if not exists ix_pay_inputs_company_id_pay_period_id on hrm.pay_inputs (company_id, pay_period_id); -- foreign key fk_pay_inputs_pay_period_id
create index if not exists ix_pay_inputs_company_id_component_id on hrm.pay_inputs (company_id, component_id); -- foreign key fk_pay_inputs_component_id
create index if not exists ix_pay_inputs_company_id_consumed_by_run_id on hrm.pay_inputs (company_id, consumed_by_run_id); -- foreign key fk_pay_inputs_consumed_by_run_id
create index if not exists ix_pay_inputs_company_id_import_batch_id on hrm.pay_inputs (company_id, import_batch_id); -- foreign key fk_pay_inputs_import_batch_id

-- hrm.pay_periods: Payroll calendar per pay group [PAY-01, PAY-38]
create table if not exists hrm.pay_periods (
    id uuid not null,
    company_id uuid not null,
    pay_group_id uuid not null,
    period_no integer not null,
    tax_year integer not null,
    start_date date not null,
    end_date date not null,
    cut_off_date date not null,
    payment_date date not null,
    status text not null,
    created_at timestamptz not null,
    created_by uuid not null,
    updated_at timestamptz not null,
    updated_by uuid not null,
    row_version bigint not null default 1,
    constraint pk_pay_periods primary key (id),
    constraint uq_pay_periods_pay_group_id_start_date unique (pay_group_id, start_date),
    constraint uq_pay_periods_pay_group_id_tax_year_period_no unique (pay_group_id, tax_year, period_no),
    constraint uq_pay_periods_company_id_id unique (company_id, id),
    constraint ck_pay_periods_status check (status in ('future', 'open', 'processing', 'closed')),
    constraint ck_pay_periods_dates check (start_date <= cut_off_date and start_date <= end_date),
    constraint ex_pay_periods_pay_group_id_dates exclude using gist (pay_group_id with =, daterange(start_date, end_date, '[]') with &&)
);
create index if not exists ix_pay_periods_company_id_pay_group_id on hrm.pay_periods (company_id, pay_group_id); -- foreign key fk_pay_periods_pay_group_id

-- hrm.pay_result_lines: PayResultLines [PAY-06, PAY-29, PAY-30]
create table if not exists hrm.pay_result_lines (
    id uuid not null,
    company_id uuid not null,
    result_id uuid not null,
    pay_period_id uuid not null,
    employment_id uuid not null,
    component_id uuid not null,
    amount numeric(19,4) not null,
    units numeric(19,6),
    rate numeric(19,10),
    period_start date,
    cost_allocation jsonb not null,
    created_at timestamptz not null,
    created_by uuid not null,
    updated_at timestamptz not null,
    updated_by uuid not null,
    row_version bigint not null default 1,
    constraint pk_pay_result_lines primary key (id),
    constraint uq_pay_result_lines_company_id_id unique (company_id, id)
);
create index if not exists ix_pay_result_lines_result_id on hrm.pay_result_lines (result_id); -- listed in the data design
create index if not exists ix_pay_result_lines_company_id_component_id_pay_period_id on hrm.pay_result_lines (company_id, component_id, pay_period_id); -- listed in the data design
create index if not exists ix_pay_result_lines_company_id_result_id on hrm.pay_result_lines (company_id, result_id); -- foreign key fk_pay_result_lines_result_id

-- hrm.pay_result_reversals: Reversal of a single payslip after approval and before payment (FR-XM-27); after payment correct by adjustment or off-cycle run [FR-XM-27, PAY-14]
create table if not exists hrm.pay_result_reversals (
    id uuid not null,
    company_id uuid not null,
    result_id uuid not null,
    reason text not null,
    approved_by uuid not null,
    reversed_at timestamptz not null,
    created_at timestamptz not null,
    created_by uuid not null,
    constraint pk_pay_result_reversals primary key (id),
    constraint uq_pay_result_reversals_result_id unique (result_id)
);
create index if not exists ix_pay_result_reversals_company_id on hrm.pay_result_reversals (company_id); -- foreign key fk_pay_result_reversals_company_id
create index if not exists ix_pay_result_reversals_company_id_result_id on hrm.pay_result_reversals (company_id, result_id); -- foreign key fk_pay_result_reversals_result_id
create index if not exists ix_pay_result_reversals_approved_by on hrm.pay_result_reversals (approved_by); -- foreign key fk_pay_result_reversals_approved_by
create or replace trigger tg_pay_result_reversals_append_only before update or delete on hrm.pay_result_reversals for each row execute function hrm.tg_refuse_change();
create or replace trigger tg_pay_result_reversals_no_truncate before truncate on hrm.pay_result_reversals for each statement execute function hrm.tg_refuse_change();

-- hrm.pay_results: Net result per employee per run; append-only once the run is locked (PAY-33) [PAY-12, PAY-28, PAY-33, FR-XM-27]
create table if not exists hrm.pay_results (
    id uuid not null,
    company_id uuid not null,
    pay_run_id uuid not null,
    employment_id uuid not null,
    tax_year integer not null,
    pay_period_id uuid not null,
    gross numeric(19,4) not null,
    deductions numeric(19,4) not null,
    net numeric(19,4) not null,
    employer_cost numeric(19,4) not null,
    taxable_income_ytd numeric(19,4) not null,
    tax_ytd numeric(19,4) not null,
    worked_days numeric(19,6) not null,
    paid_days numeric(19,6) not null,
    corrects_result_id uuid,
    created_at timestamptz not null,
    created_by uuid not null,
    updated_at timestamptz not null,
    updated_by uuid not null,
    row_version bigint not null default 1,
    constraint pk_pay_results primary key (id),
    constraint uq_pay_results_pay_run_id_employment_id unique (pay_run_id, employment_id),
    constraint uq_pay_results_company_id_id unique (company_id, id)
);
create index if not exists ix_pay_results_employment_id_tax_year on hrm.pay_results (employment_id, tax_year); -- listed in the data design
create index if not exists ix_pay_results_company_id_pay_run_id on hrm.pay_results (company_id, pay_run_id); -- foreign key fk_pay_results_pay_run_id
create index if not exists ix_pay_results_company_id_employment_id on hrm.pay_results (company_id, employment_id); -- foreign key fk_pay_results_employment_id
create index if not exists ix_pay_results_company_id_pay_period_id on hrm.pay_results (company_id, pay_period_id); -- foreign key fk_pay_results_pay_period_id
create index if not exists ix_pay_results_company_id_corrects_result_id on hrm.pay_results (company_id, corrects_result_id); -- foreign key fk_pay_results_corrects_result_id

-- hrm.pay_run_employees: Who is in a run, the frozen input snapshot, status and validation flags [PAY-09, PAY-11, PAY-31]
create table if not exists hrm.pay_run_employees (
    id uuid not null,
    company_id uuid not null,
    pay_run_id uuid not null,
    employment_id uuid not null,
    period_start date not null,
    period_end date not null,
    run_kind text not null,
    run_status text not null,
    snapshot jsonb not null,
    snapshot_hash bytea not null,
    validation_flags text[] not null default '{}',
    hold_id uuid,
    status text not null,
    created_at timestamptz not null,
    created_by uuid not null,
    updated_at timestamptz not null,
    updated_by uuid not null,
    row_version bigint not null default 1,
    constraint pk_pay_run_employees primary key (id),
    constraint uq_pay_run_employees_pay_run_id_employment_id unique (pay_run_id, employment_id),
    constraint ck_pay_run_employees_status check (status in ('included', 'excluded', 'held', 'calculated', 'error')),
    constraint ex_pay_run_employees_employment_id_period exclude using gist (employment_id with =, daterange(period_start, period_end, '[]') with &&) where (run_kind in ('regular','final_settlement') and run_status <> 'cancelled')
);
create index if not exists ix_pay_run_employees_company_id on hrm.pay_run_employees (company_id); -- foreign key fk_pay_run_employees_company_id
create index if not exists ix_pay_run_employees_company_id_pay_run_id on hrm.pay_run_employees (company_id, pay_run_id); -- foreign key fk_pay_run_employees_pay_run_id
