    constraint uq_shifts_company_id_id unique (company_id, id),
    constraint ck_shifts_code_code check (length(code) between 1 and 40 and code = btrim(code)),
    constraint ck_shifts_name_i18n_object check (jsonb_typeof(name_i18n) = 'object'),
    constraint ck_shifts_shift_type check (shift_type in ('fixed', 'flexible', 'rotating', 'split', 'night', 'continuous'))
);
create unique index if not exists uq_shifts_company_id_code on hrm.shifts (company_id, lower(code)) where (not is_deleted);
create index if not exists ix_shifts_company_id_policy_id on hrm.shifts (company_id, policy_id); -- foreign key fk_shifts_policy_id

-- hrm.statutory_returns: Generated registers and returns (EOBI, social security, withholding statements, tax certificates) [CPL-02, CPL-04, CPL-05]
create table if not exists hrm.statutory_returns (
    id uuid not null,
    company_id uuid not null,
    return_code text not null,
    period_label text not null,
    compliance_task_id uuid,
    employment_id uuid,
    generated_document_id uuid not null,
    source_run_ids uuid[] not null default '{}',
    created_at timestamptz not null,
    created_by uuid not null,
    constraint pk_statutory_returns primary key (id),
    constraint ck_statutory_returns_return_code_code check (length(return_code) between 1 and 40 and return_code = btrim(return_code))
);
create index if not exists ix_statutory_returns_company_id_return_code_period_label on hrm.statutory_returns (company_id, return_code, period_label); -- listed in the data design
create index if not exists ix_statutory_returns_employment_id on hrm.statutory_returns (employment_id); -- listed in the data design
create index if not exists ix_statutory_returns_company_id_compliance_task_id on hrm.statutory_returns (company_id, compliance_task_id); -- foreign key fk_statutory_returns_compliance_task_id
create index if not exists ix_statutory_returns_company_id_employment_id on hrm.statutory_returns (company_id, employment_id); -- foreign key fk_statutory_returns_employment_id
create index if not exists ix_statutory_returns_company_id_generated_document_id on hrm.statutory_returns (company_id, generated_document_id); -- foreign key fk_statutory_returns_generated_document_id
create or replace trigger tg_statutory_returns_append_only before update or delete on hrm.statutory_returns for each row execute function hrm.tg_refuse_change();
create or replace trigger tg_statutory_returns_no_truncate before truncate on hrm.statutory_returns for each statement execute function hrm.tg_refuse_change();

-- hrm.statutory_table_rows: StatutoryTableRows [PAY-17, PAY-20, PAY-21]
create table if not exists hrm.statutory_table_rows (
    id uuid not null,
    table_id uuid not null,
    seq integer not null,
    lower_bound numeric(19,4),
    upper_bound numeric(19,4),
    fixed_amount numeric(19,4),
    currency_code char(3),
    rate numeric(19,10),
    key text,
    attributes jsonb not null,
    created_at timestamptz not null,
    created_by uuid not null,
    updated_at timestamptz not null,
    updated_by uuid not null,
    row_version bigint not null default 1,
    constraint pk_statutory_table_rows primary key (id),
    constraint uq_statutory_table_rows_table_id_seq unique (table_id, seq),
    constraint ck_statutory_table_rows_key_code check (length(key) between 1 and 40 and key = btrim(key)),
    constraint ck_statutory_table_rows_bounds check (lower_bound is null or upper_bound is null or lower_bound < upper_bound),
    constraint ex_statutory_table_rows_table_id_key_bounds exclude using gist (table_id with =, (coalesce(key, '')) with =, numrange(lower_bound, upper_bound) with &&)
);

-- hrm.statutory_tables: Pack-supplied, tenant-overridable rate and slab tables (income tax slabs, EOBI, PESSI/SESSI, WWF, minimum wage) [PAY-17, PAY-20, PAY-21, POL-04, CPL-04]
create table if not exists hrm.statutory_tables (
    id uuid not null,
    code text not null,
    company_id uuid,
    company_scope uuid generated always as (coalesce(company_id, '00000000-0000-0000-0000-000000000000'::uuid)) stored not null,
    source text not null,
    kind text not null,
    description_i18n jsonb not null,
    pack_version text,
    valid_from date not null,
    valid_to date,
    created_at timestamptz not null,
    created_by uuid not null,
    updated_at timestamptz not null,
    updated_by uuid not null,
    row_version bigint not null default 1,
    constraint pk_statutory_tables primary key (id),
    constraint ck_statutory_tables_code_code check (length(code) between 1 and 40 and code = btrim(code)),
    constraint ck_statutory_tables_source check (source in ('pack', 'tenant')),
    constraint ck_statutory_tables_kind check (kind in ('slab', 'rate', 'ceiling', 'lookup')),
    constraint ck_statutory_tables_description_i18n_object check (jsonb_typeof(description_i18n) = 'object'),
    constraint ck_statutory_tables_valid_to check (valid_to is null or valid_to > valid_from),
    constraint ex_statutory_tables_company_scope_code exclude using gist (company_scope with =, code with =, daterange(valid_from, valid_to, '[)') with &&)
);
create index if not exists ix_statutory_tables_company_id on hrm.statutory_tables (company_id); -- foreign key fk_statutory_tables_company_id

-- hrm.tax_declaration_lines: TaxDeclarationLines [PAY-19]
create table if not exists hrm.tax_declaration_lines (
    id uuid not null,
    declaration_id uuid not null,
    kind text not null,
    declared_amount numeric(19,4) not null,
    verified_amount numeric(19,4),
    file_ids uuid[] not null default '{}',
    created_at timestamptz not null,
    created_by uuid not null,
    updated_at timestamptz not null,
    updated_by uuid not null,
    row_version bigint not null default 1,
    constraint pk_tax_declaration_lines primary key (id),
    constraint ck_tax_declaration_lines_kind_code check (length(kind) between 1 and 40 and kind = btrim(kind))
);
create index if not exists ix_tax_declaration_lines_declaration_id on hrm.tax_declaration_lines (declaration_id); -- foreign key fk_tax_declaration_lines_declaration_id

-- hrm.tax_declarations: TaxDeclarations [PAY-19]
create table if not exists hrm.tax_declarations (
    id uuid not null,
    company_id uuid not null,
    employment_id uuid not null,
    tax_year integer not null,
    status text not null,
    created_at timestamptz not null,
    created_by uuid not null,
    updated_at timestamptz not null,
    updated_by uuid not null,
    row_version bigint not null default 1,
    constraint pk_tax_declarations primary key (id),
    constraint uq_tax_declarations_employment_id_tax_year unique (employment_id, tax_year),
    constraint ck_tax_declarations_status check (status in ('draft', 'submitted', 'verified', 'rejected'))
);
create index if not exists ix_tax_declarations_company_id on hrm.tax_declarations (company_id); -- foreign key fk_tax_declarations_company_id
create index if not exists ix_tax_declarations_company_id_employment_id on hrm.tax_declarations (company_id, employment_id); -- foreign key fk_tax_declarations_employment_id

-- hrm.training_bonds: TrainingBonds [LND-06]
create table if not exists hrm.training_bonds (
    id uuid not null,
    company_id uuid not null,
    employment_id uuid not null,
    enrollment_id uuid,
    bond_amount numeric(19,4) not null,
    currency_code char(3) not null,
    obligation_until date not null,
    recovery_rule text not null,
    status text not null,
    created_at timestamptz not null,
    created_by uuid not null,
    updated_at timestamptz not null,
    updated_by uuid not null,
    row_version bigint not null default 1,
    constraint pk_training_bonds primary key (id),
    constraint ck_training_bonds_recovery_rule check (recovery_rule in ('full', 'pro_rata')),
    constraint ck_training_bonds_status check (status in ('active', 'fulfilled', 'recovered', 'waived'))
);
create index if not exists ix_training_bonds_company_id on hrm.training_bonds (company_id); -- foreign key fk_training_bonds_company_id
create index if not exists ix_training_bonds_company_id_employment_id on hrm.training_bonds (company_id, employment_id); -- foreign key fk_training_bonds_employment_id
create index if not exists ix_training_bonds_company_id_enrollment_id on hrm.training_bonds (company_id, enrollment_id); -- foreign key fk_training_bonds_enrollment_id

-- hrm.training_requirements: Materialized due items per employee for compliance reporting and reminders [LND-04]
create table if not exists hrm.training_requirements (
    id uuid not null,
    company_id uuid not null,
    rule_id uuid not null,
    employment_id uuid not null,
    due_date date not null,
    learning_record_id uuid,
    status text not null,
    created_at timestamptz not null,
    created_by uuid not null,
    updated_at timestamptz not null,
    updated_by uuid not null,
    row_version bigint not null default 1,
    constraint pk_training_requirements primary key (id),
    constraint uq_training_requirements_rule_id_employment_id_due_date unique (rule_id, employment_id, due_date),
    constraint ck_training_requirements_status check (status in ('due', 'overdue', 'completed', 'waived'))
);
create index if not exists ix_training_requirements_company_id on hrm.training_requirements (company_id); -- foreign key fk_training_requirements_company_id
create index if not exists ix_training_requirements_company_id_rule_id on hrm.training_requirements (company_id, rule_id); -- foreign key fk_training_requirements_rule_id
create index if not exists ix_training_requirements_company_id_employment_id on hrm.training_requirements (company_id, employment_id); -- foreign key fk_training_requirements_employment_id
create index if not exists ix_training_requirements_company_id_learning_record_id on hrm.training_requirements (company_id, learning_record_id); -- foreign key fk_training_requirements_learning_record_id

