comment on table hrm.statutory_table_rows is 'Requirements: PAY-17, PAY-20, PAY-21. Pending rule (S1.36, placeholder hrm.todo_statutory_table_rows_lock): Immutable by trigger once the parent version is effective or referenced by any run; change by a new table version. Source: hrm-pay.yaml.';
comment on column hrm.statutory_table_rows.table_id is 'fk hrm.statutory_tables';
comment on column hrm.statutory_table_rows.currency_code is 'for money bounds';
comment on column hrm.statutory_table_rows.key is 'for lookups, e.g. province code';
comment on table hrm.statutory_tables is 'Pack-supplied, tenant-overridable rate and slab tables (income tax slabs, EOBI, PESSI/SESSI, WWF, minimum wage). Requirements: PAY-17, PAY-20, PAY-21, POL-04, CPL-04. Pack updates create new versions with a future valid_from. Source: hrm-pay.yaml.';
comment on column hrm.statutory_tables.code is 'e.g. pk.income_tax.salaried';
comment on column hrm.statutory_tables.company_id is 'fk org.companies; null = pack or tenant-wide value';
comment on column hrm.statutory_tables.company_scope is 'generated always as coalesce(company_id, nil uuid) stored';
comment on table hrm.tax_declaration_lines is 'Requirements: PAY-19. Source: hrm-pay.yaml.';
comment on column hrm.tax_declaration_lines.declaration_id is 'fk hrm.tax_declarations';
comment on column hrm.tax_declaration_lines.kind is 'exemption or credit type from pack, e.g. zakat, donation, pension fund';
comment on table hrm.tax_declarations is 'Requirements: PAY-19. Source: hrm-pay.yaml.';
comment on column hrm.tax_declarations.employment_id is 'fk hrm.employments';
comment on table hrm.training_bonds is 'Requirements: LND-06. Pending rule (S1.43, placeholder hrm.todo_training_bonds_final_settlement_recovery): Active bonds appear in final settlement as bond_recovery (LND-06). Source: hrm-talent.yaml.';
comment on column hrm.training_bonds.employment_id is 'fk hrm.employments';
comment on column hrm.training_bonds.enrollment_id is 'fk hrm.session_enrollments';
comment on table hrm.training_requirements is 'Materialized due items per employee for compliance reporting and reminders. Requirements: LND-04. Source: hrm-talent.yaml.';
comment on column hrm.training_requirements.rule_id is 'fk hrm.mandatory_training_rules';
comment on column hrm.training_requirements.employment_id is 'fk hrm.employments';
comment on column hrm.training_requirements.learning_record_id is 'fk hrm.learning_records';
